}

function mapVariables(varsEl) {
  if (!varsEl) return undefined;
  const map = (v) => ({
    id: v.id,
    name: v.name,
    type: v.type,
    subType: v.subType,
    canonicalId: v.canonicalId,
    elementId: v.elementId,
    default: v.default,
  });
  return {
    inputs: (varsEl.input ?? []).map(map),
    inputOutputs: (varsEl.inputOutput ?? []).map(map),
